import{_ as e,o as i,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Real-Time Data Anonymization the Serverless Way Demo","description":"","frontmatter":{"title":"Real-Time Data Anonymization the Serverless Way Demo","date":"2021-10-18T00:00:00.000Z","updated":"2021-10-19T00:00:00.000Z","tags":["Ceph","Serverless","Data Anonymization","Real","Time Processing","MicroShift"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Real-Time_Data_Anonymization_the_Serverless_Way_Demo.md","filePath":"posts/2021/Real-Time_Data_Anonymization_the_Serverless_Way_Demo.md","lastUpdated":1780459816000}'),o={name:"posts/2021/Real-Time_Data_Anonymization_the_Serverless_Way_Demo.md"};function r(n,a,s,h,u,d){return i(),l("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-cubecon-2021-实时数据匿名化演示" tabindex="-1">会议主题：CubeCon 2021 实时数据匿名化演示 <a class="header-anchor" href="#会议主题-cubecon-2021-实时数据匿名化演示" aria-label="Permalink to &quot;会议主题：CubeCon 2021 实时数据匿名化演示&quot;">​</a></h4><h4 id="会议时间-2021年" tabindex="-1">会议时间：2021年 <a class="header-anchor" href="#会议时间-2021年" aria-label="Permalink to &quot;会议时间：2021年&quot;">​</a></h4><h4 id="会议地点-cubecon-2021" tabindex="-1">会议地点：CubeCon 2021 <a class="header-anchor" href="#会议地点-cubecon-2021" aria-label="Permalink to &quot;会议地点：CubeCon 2021&quot;">​</a></h4><h4 id="主讲人-主讲人姓名" tabindex="-1">主讲人：[主讲人姓名] <a class="header-anchor" href="#主讲人-主讲人姓名" aria-label="Permalink to &quot;主讲人：[主讲人姓名]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>演示目的</strong>：</p><ul><li>展示如何在Ceph存储系统中实时自动模糊图像中的人脸和车牌。</li></ul></li><li><p><strong>技术栈与工具</strong>：</p><ul><li><strong>存储系统</strong>：Ceph</li><li><strong>配置与部署</strong>：Rook Operator</li><li><strong>无服务器函数</strong>：基于KDA无服务器框架</li><li><strong>消息通知</strong>：通过RabbitMQ消息总线传递，由Private MQ Operator部署</li></ul></li><li><p><strong>系统配置与部署流程</strong>：</p><ul><li>从干净的MicroShift节点开始，使用GitHub上的代码进行配置和部署。</li><li>安装Rook Operator，包括基础组件和自定义YAML文件。</li><li>部署Ceph集群，包括OSDs和其他存储后端。</li><li>安装Redis网关和对象存储前端，以及必要的工具箱。</li></ul></li><li><p><strong>创建存储桶</strong>：</p><ul><li>定义存储类，并通过对象存储桶声明（Object Bucket Claim）配置存储桶。</li><li>配置特殊标签以关联通知，允许明文传输RabbitMQ用户和密码。</li></ul></li><li><p><strong>配置环境参数</strong>：</p><ul><li>设置Redis网关服务名称和访问密钥。</li><li>安装RabbitMQ Operator并创建RabbitMQ实例。</li></ul></li><li><p><strong>配置RabbitMQ</strong>：</p><ul><li>清理并声明交换机，配置队列绑定和路由键。</li><li>创建Ceph存储桶主题的CRD，定义通知的端点和参数。</li></ul></li><li><p><strong>安装和配置KDA</strong>：</p><ul><li>使用Helm安装KDA，定义无服务器函数以执行模糊处理。</li><li>创建秘密文件以提供凭证，确保无服务器函数能够访问Redis网关。</li></ul></li><li><p><strong>演示上传图像</strong>：</p><ul><li>上传图像后，系统会发送通知到RabbitMQ，KDA会启动RabbitMQ消费者进行模糊处理。</li><li>查看日志确认模糊处理成功，并将处理后的图像上传回Ceph存储桶。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>确认演示中使用的所有组件和配置均正常工作，确保系统的稳定性和可靠性。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>收集反馈并解答与会者的疑问。</li><li>根据反馈进一步优化系统配置和部署流程。</li></ul><h4 id="会议结束语" tabindex="-1">会议结束语： <a class="header-anchor" href="#会议结束语" aria-label="Permalink to &quot;会议结束语：&quot;">​</a></h4><ul><li>主讲人感谢大家的参与，并欢迎提出任何问题和反馈。</li></ul>',13)])])}const p=e(o,[["render",r]]);export{_ as __pageData,p as default};
